struct KeychainStore {
    static func set(_ value:String,key:String){let data=Data(value.utf8);SecItemDelete([kSecClass:kSecClassGenericPassword,kSecAttrAccount:key]as CFDictionary);SecItemAdd([kSecClass:kSecClassGenericPassword,kSecAttrAccount:key,kSecValueData:data,kSecAttrAccessible:kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly]as CFDictionary,nil)}
    static func get(_ key:String)->String{var result:CFTypeRef?;let q:[CFString:Any]=[kSecClass:kSecClassGenericPassword,kSecAttrAccount:key,kSecReturnData:true,kSecMatchLimit:kSecMatchLimitOne];guard SecItemCopyMatching(q as CFDictionary,&result)==errSecSuccess,let data=result as? Data else{return""};return String(data:data,encoding:.utf8)??""}
}

