    static func request(_ url:URL,method:String="GET",token:String?=nil,json:Any?=nil)async throws->(Data,HTTPURLResponse){var req=URLRequest(url:url);req.httpMethod=method;req.setValue("application/vnd.github+json",forHTTPHeaderField:"Accept");req.setValue("2022-11-28",forHTTPHeaderField:"X-GitHub-Api-Version");if let token,!token.isEmpty{req.setValue("token \(token)",forHTTPHeaderField:"Authorization")};if let json{req.setValue("application/json",forHTTPHeaderField:"Content-Type");req.httpBody=try JSONSerialization.data(withJSONObject:json)};let(data,response)=try await URLSession.shared.data(for:req);guard let http=response as? HTTPURLResponse else{throw NSError(domain:"A17Y",code:1,userInfo:[NSLocalizedDescriptionKey:"Invalid HTTP response"])};return(data,http)}
