    static func fetchCatalogData()async throws->Data{let(data,response)=try await URLSession.shared.data(from:catalogURL);guard(response as?HTTPURLResponse)?.statusCode==200 else{throw NSError(domain:"A17Y",code:10,userInfo:[NSLocalizedDescriptionKey:"Firmware catalog unavailable"])};return data}
