    static func officialFirmwareMatch(catalog:Data,fileName:String,hash:String)->Bool{guard let root=try?JSONSerialization.jsonObject(with:catalog)else{return false};func scan(_ value:Any)->Bool{if let d=value as?[String:Any]{if let h=d["sha256"]as?String,let n=d["name"]as?String,h.caseInsensitiveCompare(hash)==.orderedSame,n.caseInsensitiveCompare(fileName)==.orderedSame{return true};return d.values.contains(where:scan)};if let a=value as?[Any]{return a.contains(where:scan)};return false};return scan(root)}
    static func uploadLog(token:String,name:String,data:Data,hash:String,remote:Set<String>)async throws->String{guard token.hasPrefix("ghp_")else{throw NSError(domain:"A17Y",code:11,userInfo:[NSLocalizedDescriptionKey:"Classic GitHub PAT required"])};guard !remote.contains(hash)else{throw NSError(domain:"A17Y",code:17,userInfo:[NSLocalizedDescriptionKey:"This log already exists in the repository"])};let safe=name.replacingOccurrences(of:"[^A-Za-z0-9._-]",with:"_",options:.regularExpression),path="tests/replays/mobile-\(Int(Date().timeIntervalSince1970*1000))-\(safe)";let(reply,response)=try await request(URL(string:"https://api.github.com/repos/\(repo)/contents/\(path)")!,method:"PUT",token:token,json:["message":"Import MT12 log \(safe) [\(hash)]","content":data.base64EncodedString(),"branch":"main"]);guard response.statusCode==201,let obj=try JSONSerialization.jsonObject(with:reply)as?[String:Any],let content=obj["content"]as?[String:Any],!((content["sha"]as?String)??"").isEmpty else{throw NSError(domain:"A17Y",code:12,userInfo:[NSLocalizedDescriptionKey:"GitHub did not confirm upload"])};return path}
    static func sync(root:URL,token:String)async throws->String{guard root.startAccessingSecurityScopedResource()else{throw NSError(domain:"A17Y",code:13,userInfo:[NSLocalizedDescriptionKey:"Folder permission unavailable"])};defer{root.stopAccessingSecurityScopedResource()};guard validateMT12(root)else{throw NSError(domain:"A17Y",code:14,userInfo:[NSLocalizedDescriptionKey:"Selected folder is not an MT12 root"])};let logs=root.appendingPathComponent("LOGS",isDirectory:true),files=try FileManager.default.contentsOfDirectory(at:logs,includingPropertiesForKeys:nil).filter{$0.pathExtension.lowercased()=="csv"};var imported=Set(UserDefaults.standard.stringArray(forKey:"importedHashes") ?? []);let remote=await repositoryLogHashes();var lines:[String]=[],count=0;for file in files{let data=try Data(contentsOf:file),hash=sha256(data);if imported.contains(hash)||remote.contains(hash){lines.append("KNOWN \(file.lastPathComponent)");imported.insert(hash);continue};let path=try await uploadLog(token:token,name:file.lastPathComponent,data:data,hash:hash,remote:remote);imported.insert(hash);UserDefaults.standard.set(Array(imported),forKey:"importedHashes");count+=1;lines.append("UPLOADED \(file.lastPathComponent) → \(path)")};return "Uploaded \(count) new logs.\n"+lines.joined(separator:"\n")}
